INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1019222-ee380', 'stk-user6800', 'EE 380', 'info', '{"desc": "بنود تساعد في تقييم المقرر:\n\nجودة المقرر بشكل عام جيد جدا\n\nالمواضيع التي يغطيها المقرر أساسيات الكنترول, يعني جدا مهم لأهل الكنترول\n\nالكتاب المستخدم للمقرر دروف\nالأسئلة والأمثلة المستخدمة في المقرر\nمدى فائدته في الناحية التطبيقية\n\nإذا ناوي تنزل مادة\n\nCISE 418 as a technical elective\n\nنزلها على طول بعد ال 380 مبااااشرة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/3", "user": "user6800", "ts": 1333641945000, "tid": 120704, "pn": 3}}', 1333641945000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1207279-ee380', 'stk-user1091', 'EE 380', 'info', '{"desc": "السلام عليكم\n\nفي رأيي الصراحة هذا الكورس مفاهيمه بسيطة وسهلة بشكل عام\n\nلكن بعض الدكاترة قد تحصل منه صعوبة في الاختبارات\n\nوالصراحة الكتاب المستخدم في رأيي (Modern Control System) لا يكفي للمادة لأنك تحتاج أمثلة وشرح وهذا غير كافي في الكتاب\n\nلكن هناك شيء مهم\n\nهذا الكورس أساسي في فهم نظرية التحكم (لكن لا يكفي) للي يبغى يشتغل مهندس تحكم وقياسات\n\nلكن هناك كورس أهم منه وهو EE 434 Industrial instrumentation وهو عن هندسة القياسات\nبالاضافة إلى الكورسات اللي يقدمها قسم هندسة التحكم في الجامعة ممكن تاخذها كإضافة على مواد التخصص (حسب استطاعتك) وأنا سويتها\n\nالشركات البتروكيماوية مشاريعها كثيرة جدا في مجال التحكم والقياسات\n\nفاللي يبغى يشتغل في هذا المجال أنصحه ياخذ 434 بعد 380 وإن كان ما في بينهم تداخل كبير\n\nالله يوفق الجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/4", "user": "user1091", "ts": 1365400091000, "tid": 120704, "pn": 4}}', 1365400091000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467227-ee380', 'stk-abo-da7m', 'EE 380', 'info', '{"desc": "أخذته فصل 161 مع الدكتور أحمد مسعود\n\nجودة المقرر بشكل عام\n\nمهم وممتاز\n\nالمواضيع التي يغطيها المقرر\n\nالمقرر عبارة عن مقدمة عن نظرية التحكم. يتكلم عن الأدوات المستخدمة لوصف نظام معين، كيفية السيطرة على الهالنظام وكيف نخليه يسوي اللي نبغاه منه.\n\nهذا الSyllabus:\nSyllabus EE380 Sem 161.pdf\n\nالكتاب المستخدم للمقرر\n\nModern Control System 12th edition, by R. Dorf, R. Bishop, Prentice-Hall, 2011.\nدسم وشامل لكنه صعب وسيء بسرد المواضيع والانتقال بينهن.\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nاللي بالكتاب كافي لكن غير مفيد لإن المقرر يعتمد على الدكتور وطريقته، وصعب تمر على كل أسئلة الكتاب.\n\nمدى فائدته في الناحية التطبيقية\n\nمفيد جدا وأساسي للي يبغى يكمل بهالمجال\n\nملاحظات:\n\n* المقرر موب coordinated ويختلف وبكل شيء من دكتور لدكتور (تقسيم الدرجات، اسلوب الموضوعات، الاختبارات) ، عشان كذا أفضل تسأل عن الدكتور وطريقته قبل تنزل عنده.\n\n* سلسلة المحاضرات هذي - على الرغم من قدمها- فادتن فايدة عظيمة:\n\nhttps://www.youtube.com/watch?v=vVFDm\\_\\_CdQw\n\n* يعتبر من مقررات المستوى 3 متوسطة الثقل إلى الثقييلة (المقرر موب طويل بس مفاهيمة دسمة شوي)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/5", "user": "abo-da7m", "ts": 1485706674000, "tid": 120704, "pn": 5}}', 1485706674000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1485159-ee380', 'stk-mr.a1', 'EE 380', 'info', '{"desc": "Term 171 with Ahmad Masoud\n\nقبل ما تقرأ التالي ، المادة مختلفة حسب الدكتور.\n\nجودة المقرر بشكل عام\nجيد ، يعطيك مقدمة في هندسة التحكم.\n\nالمواضيع التي يغطيها المقرر\nIntroduction to Control Engineering\nModeling\nState Space Equations\nSystem Performance\nStability\nRoot Locus Method\nFrequency Response Methods\nStability in Frequency Domain\nDesign of Feedback Control Systems\nالمنهج مليان بالمواضيع ، وكلها أشياء جديدة ممكن أول مرة تمر عليك.\n\nالكتاب المستخدم للمقرر\nمرجع ، المذاكرة منه صعبة اشوي ومتعبة ، وفيه حشو كلام.\n\nالأسئلة والأمثلة المستخدمة في المقرر\nبعض المواضيع افكارها قليلة فتتشابه مع اسئلة الاختبارات ، وبعضها يكون مستوى أسئلة الاختبارات أصعب بكثير.\n\nمدى فائدته في الناحية التطبيقية\nمقدمة في هندسة التحكم ، ممكن ما راح تستوعبه بشكل جيد بسبب ضعف وقلة التطبيق في المادة ، فإذا كنت مهتم ممكن تتابع في مواد متقدمة عشان تفهم التحكم أكثر.\n\nإضافات:\n١. بالنسبة لي كان أحد المقررات المرهقة والجديدة علي ، يحتاج متابعة أول بأول عشان تستوعبه لأعلى درجة ممكنة.\n٢. لاب المادة من أسوأ اللابات اللي أخذتها ، التجارب غير مرتبة مع الليكتشر ، وفيه تجارب ما لها ارتباط بالليكتشر من الأساس.\n\nعموما ، حاول تستفيد من المقرر قد ما تقدر ، ولا تتوقع إنه راح يعطيك فكرة شاملة عن هندسة التحكم ، هو تعريف مطول بالفرع والأدوات اللي ممكن تستخدمها في تحليل بعض نظم التحكم ، يعني ما فيه أشياء عميقة مرة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/6", "user": "Mr.A1", "ts": 1514455392000, "tid": 120704, "pn": 6}}', 1514455392000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1502212-ee380', 'stk-ali_g', 'EE 380', 'info', '{"desc": "أخذته فصل 171 مع الدكتور أحمد مسعود\n\nجودة المقرر بشكل عام:\nمهم جداااااااااااااااا\n\nالمواضيع التي يغطيها المقرر:\nالدروس في المقرر مكملين مع بعض فخليك مراجع الدروس مع الدكتور\n\nالكتاب المستخدم للمقرر:\nلا انصح فيه كمذاكرة\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nركز على نوتة الدكتور واليوتيوب كمصدر\n\nمدى فائدته في الناحية التطبيقية:\nمفيد جدا وبذات في مجال Power بينهم ترابط فمثلا في كورس ee466 راح تسوي transient analysis on a system ومشكال delay و underdamped response في النظام\nوبرضو كورس ee462 الموتر والجينيريتر احيانا حالات نادرة مثل تغير load, المولد تروح منه 5% من طاقته الكهربائية مثلا. فاذا بتخش بور انصح تركز في ذي المادة.\n\nملاحظات:\n*انصح تاخذ مادة CISE418, EE433 بعدها.\n*هذا يعتبر قسم بسيط من مجال التحكم راح تدرس فقط من نوعية النظام :DC Motor ,non-Linearity=0%,Second order system\n*اختبار النهائي اغلب الاسئلة كونسيبت.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/7", "user": "Ali_G", "ts": 1541899949000, "tid": 120704, "pn": 7}}', 1541899949000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1518398-ee380', 'stk-khc800', 'EE 380', 'info', '{"desc": "فصل 191 مع الدكتور سمير البيات\n\nجودة المقرر بشكل عام:\nالمقرر ممتاز، والمواضيع اللي يغطيها أساسية جدا في مجال التحكم، ولكن ترتيب المواضيع ربما يحتاج له إعادة نظر\n\nالمواضيع التي يغطيها المقرر:\n\nالمقرر بشكل عام يركز على ثلاث مهارات رئيسة:\n\n1 - النمذجة (Modeling): تقدر من خلالها تحول physical system إلى mathematical model عشان تستطيع تتعامل معه وتطوره إلخ إلخ…\nبتدرس: transfer functions, state space model, differential equation وكيف تنتقل من هذا إلى هذا، وإيش ميزة كل واحد\n\n2 - التحليل (Analysis): بتدرس في هذه المرحلة كيف تحلل وتقيم أداء النظام System performance…\nالمواضيع تشمل: time domain analysis, root locus, Routh-Hurwitz criterion, Bode plot, and Nyquist plot\n\n3 - التصميم (Design): في هذه المرحلة بتتعلم كيف تخلي السستم حقك يعطي الأداء المطلوب منه، يعني لو عندك سستم مضروب تقدر تطوره من ناحية الاستقرار أو السرعة أو نسبة الخطأ وغيرها… وبتتعلم التصميم بطريقتين على: Bode plot and Nyquist. وبتمر كذلك على التصميم باستخدام الPID controllers.\n\nالكتاب المستخدم للمقرر:\nالكتاب متوسط، غير جيد للمذاكرة، ولكن يبقى فيه أسئلة جيدة\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nنوت الدكتور جيدة ولكن تبقى غامضة في أشياء كثير وما تكفي لحالها في المذاكرة\n\nالقناة هذي جيدة في شرح المفاهيم:\nBrian Douglas\nوكذلك القناة اللي أرسلها الأخ فوق\n\nمدى فائدته في الناحية التطبيقية:\nكورس مهم جدا جدا، ومرتبط مع الكثير من التخصصات الأخرى داخل الكهرباء، بالإضافة إلى كونه ممتع - تطبيقاته تشوفها في اشياء كثيرة أمامك: مثبت السرعة، المتحكم في درجة الحرارة، واي شي فيه فيدباك\n\nملاحظات أخرى:\nاللاب بالنسبة لي شخصيا كان ممل، تسوي أشياء ما تدري ليش، وتمشي على مانوال غثيث، وترجع الغرفة تكتب ريبورت جدا طويل، وما تفهم اللي سويته الا بعد ما تخلص الريبورت ويمكن ما تفهم أصلا.\nالكورس كذلك يعتمد على الماتلاب، وضروري أنك تعرف تستخدمه مو بس للاب، ولكن بيفيدك شخصيا في مذاكرة المادة وحل الأسئلة إلخ إلخ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/8", "user": "khc800", "ts": 1577540988000, "tid": 120704, "pn": 8}}', 1577540988000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529909-ee380', 'stk-user11634', 'EE 380', 'info', '{"desc": "Term 202 - Salim Ibrir\n\nجودة المقرر بشكل عام\n\nالمقرر جيد عموما فالمواضيع تقدم بتسلسل جيد وبينها ترابط واضح، ومن الأمور الجيدة فيه شرح استخدام الماتلاب لأغلب ما يتم دراسته أثناء المقرر.\n\nالمواضيع التي يغطيها المقرر\n\nيمكن تقسيم المقرر إلى الأجزاء الرئيسة التالية:\n\n1- النمذجة - Modeling:\n\nالخطوة الأولى لنمذجة أي نظام (System) هي إيجاد Differential Equation تمثل النظام باستعمال القوانين الفزيائية أو قوانين الهندسة الكهربائية أو غيرهما، وعند إيجادها يمكن تحويلها إلى Transfer Function باستخدام Laplace Transform. وهناك طرق أخرى لتمثيل النظام غير Transfer function، وتشمل Block Diagrams، وState Space Model، وSignal Flow Graph، ولكل طريقة مميزات وعيوب، ويمكن الانتقال من طريقة إلى أخرى باستخدام خطوات حل واضحة مشروحة في المقرر.\n\n2- أداء النظام - System Performance:\n\nيقاس أداء النظام في مجالين منفصلين، وكل منهما يركز على جانب معين من أداء النظام:\n\nأ - الوقت - Time Domain:\n\nفي الوقت تحسب عدة معايير تمثل أداء النظام، وتشمل Rise Time و Settling Time و Peak Time و Steady-State Error و Percent Overshoot. وكذلك يمكن تحديد نمط النظام سواء كان Under Damped أو Over Damped أو Critically Damped.\nب - S-domain:\n\nعند إيجاد poles النظام من Transfer Function يمكن تحديد ما إذا كان النظام مستقر (Stable) أم لا، فإذا كان هناك pole واحد موجب (في الجزء الأيمن من S-plane ) على الأقل فالنظام غير مستقر، ولكن أحيانا يصعب إيجاد poles، لذلك يلجأ لطرق أخرى لمعرفة استقرار النظام، وتشمل Routh-Hurwitz stability criterion و The root-locus method و Bode plots و Nyquist criterion.\n\n3- تحسين أداء النظام:\n\nيمكن تحسين أداء النظام بإضافة Compensator أو PID Controller إليه.\n\nالكتاب المستخدم للمقرر\n\nModern Control System 13th edition, by R. Dorf, R. Bishop, Prentice-Hall, 2017\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nأسئلة الواجب والاختبارت القديمة كافية وتغني إلى حد كبير عن أسئلة الكتاب\n\nمدى فائدته في الناحية التطبيقية\n\nالمقرر يمثل مقدمة في مجال هندسة التحكم، ولا يقدم الكثير فيما يتعلق بالجانب التطبيقي لهذا المجال المهم، باستثناء نموذج DC Motor الذي تم التركيز عليه في اللاب.\n\nإضافات:\nهذه فيديوهات مفيدة جدا لبعض مواضيع المقرر.\n\n**1- State Space Analysis for transfer function Example**\n2- Root locus Example 1\n3- Bode Plot EXAMPLE\n4- Nyquist Plot Example 1", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-380-control-engineering/120704/10", "user": "user11634", "ts": 1620486484000, "tid": 120704, "pn": 10}}', 1620486484000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1328740-ee380', 'stk-user9551', 'EE 380', 'info', '{"desc": "اهلا و سهلا\n\nالمادة نوعا ما تحتاج دكتور يشرح و الدكتور باخشوين متمكن من المادة\n\nفي وجهة نظري ان الفهم مع باخشوين يغطي 50 بالمية من الجهد في المذاكرة او اكثر\n\nاسئلة الكوزات تجي من الهوموورك مع اختلاف بسيط و المياجر حسب ما اذكر كانت متوسطة الى صعبة\n\nانا ما اذكر بالظبط لاني اخذتها معه قبل ترمين لكن المياجر اذا شديت حيلك تضمن فوق 75 الى فوق ال 80\n\nو على فكرة الافرج غالبا يكون من 50 الى 60\n\nلكن زي ما قلت لك ذاكر الاونلاين لكشر و اعرف حلول الهومووركات و طقطق على الكوزات\n\nو لا تنسى تذاكر الاولد اكزام خصوصا قبل المياجر\n\nهذي من اهم النقاط اللي تخليك تبدع في المياجر هو راح ينزل لكم اولد اكزام واحد او اثنين\n\nو انت راح تلقى في موقعه الشخصي واحد او اثنين\n\nاستفد منها جدا ،، لانه يحب الافكار يجيب افكار تمشي على اغلب الطلاب و راح تلقى اكثر من فكرة في الاولد اكزام\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee380/156771/2", "user": "user9551", "ts": 1392032052000, "tid": 156771, "pn": 2}}', 1392032052000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1411087-ee380', 'stk-d7me-7', 'EE 380', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nنادر جدا يحضر … كويزاته طويلة (الحصة كاملة) ومستواها متوسط … الهوموورك أحيانا صعب ويحتاج وقت (يعطينا أسئلة من عنده واحيانا تكون خارج المنهج شوي)\n\nأهم شي يخصص قبل الميجر حوالي ثلاث كلاسات كلها مراجعة وتمارين شبيهة بأسئلة الميجر، تصحيحه عادي\n\nهذا الاسبوع اعطانا البروجكت والظاهر انه طويييل ويعتمد عالماتلاب بالكامل\n\nالشرح صراحة ما اقدر افيدك فيه كثير (سلف ستدي) لكن الظاهر انه كويس\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee380-salim-ibrir/159917/4", "user": "D7ME-7", "ts": 1415638360000, "tid": 159917, "pn": 4}}', 1415638360000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p319915-ee380', 'stk-user1655', 'EE 380', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nشباب أنا منزل الفصل هذا ee 380 و ee360 ،،\n\n380 هذي ماني مجمع فيها أي هرجة ، وماني داري والله المادة إش تبغى أو إش الهدف منها ، الكلاس الرابع اليوم وماني فاهم أي شي !!!!\nو 360 الحمد لله مجمع شويتين ، لكن مو لذيك الدرجة ،،\n\nفياريت تعطوني نصايحكم فيما يتعلق بالمادتين هذه خصوصا 380 من ناحية المذاكرة والمراجعة ، وكمان أفضل النوتات الموجودة للمادتين ،،\n\nجزاكم الله كل خير ،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee380/66949/1", "user": "user1655", "ts": 1224349117000, "tid": 66949, "pn": 1}}', 1224349117000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1211199-ee380', 'stk-ahmad_ajr', 'EE 380', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\nأنا منزل عنده هالسمستر بعطيك كل اللي عندي.\n\nالشرح :\nالدكتور صوته ولهجته ممتازة و يعتمد في شرحه على دروس الاونلاين. بعض الأحيان يوقف بعض الطلاب يحلون بعض الأمثلة .\n\nالهوموركات:\nمن النوع اللي يكرف شوي تقريباً كل أسبوع أو أسبوع ونص يكون عندنا تسليم هومورك .أسئلة الهوموركات 80% منها من عنده و 20% من الكتاب و غالباً تكون 7 - 8 أسئلة .\n\nالتصحيح :\nلاتعليق 😁\n\nالمياجر:\nما شفت مياجر باقي الدكاترة فما أقدر أقارنه بغيره ، بشكل عام ميجر 1 ماكان صعب ومقدور عليه بس الأفرج تقريباً 55 بسبب التصحيح، الكورس نظامه أفرج يعني من صالحنا كطلاب أنه يكون نازل .\n\nأنصحك تنزل عنده في حالة أن ماعندك مشكلة مع الأونلاين لكشر + مستعد تشتغل معاه أول بأول +تتحمل تصحيحه 🥊", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee380/143234/2", "user": "ahmad_ajr", "ts": 1366109265000, "tid": 143234, "pn": 2}}', 1366109265000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p991025-ee380', 'stk-user2491', 'EE 380', 'info', '{"desc": "Lord … ~\n\n--------\n\nقسم الهندسة الكهربائية بالكامل ( ٩٠٪ ) يعتمد اعتماد كلي على فهمك للمادة وليس حفظك لها\n\nلكن احيانا تواجهك بعض المواد الشاذة عن المواد الاخزى ، وانا اقصد هنا مادتي EE 200 و EE 380\n\nهاتين المادتين تعتبر وكأنها كتاب الغاز اكثر من كونها مواد دراسية ، يعني تحس وانت تذاكرها او في الاختبارات انك قاعد تحل الغاز في مجلة معينه\n\nمثل هالمواد ( الالغاز ) تحتاج ان تكون متوقع جيد للأسئلة وطريقتها ، لأنك لو ماعرفت طريقة الاسئلة من الاختبارات القديمة او الكويزز راح تعاني في الاختبار وتتفاجئ بالطريقة\n\nالمادة سهله الى حد كبير ، وان لم تحنني الذاكرة ان اول الدروس كانت التحويل بين الارقام ( الثنائي ، العشاري ، الثماني ، السادس عشري وهكذا )\n\nفـ مثل هالدرس يجب عليك ان تفهم طريقة جيدة للتحويل بين الثائي والعشاري الى الرباعي او الثماني او السادس عشر\n\nبالاضافة يجب عليك ان تفهم تحويل اي رقم من اي اساس كان الى اي اساس اخر ، مثلا لو طلب منك تحويل رقم من اساس ٥ الى رقم من اساس ٧ ، يجب عليك فهم الطريقة بشكل جيد\n\nوبالتالي اي سؤال في الاختبار يجيبك فيه تحويلات ، سيكون الجواب بسهولة متواجد لديك بطريقه سهله\n\nوهكذا لن يجد الدكتور اي طريقة للهروب منك ، وبالتالي تصبح الاسئلة من هذا النوع في متناول اليد في الاختبار ان شاء الله\n\nونفس الشي ينطبق على SOP و POS و Truth table و Multiplexer وغيرها من الدروس\n\nالخلاصة ، حاول ان تكون انت الدكتور للمادة وفكر في اي سؤال صعب ممكن يخطئ فيه الطالب ويكون من ضمن المنهج ، وبهالطريقة اشوف انك تكون قادر كل المقدرة ( بعد توفيق الله ) انك تسيطر عليها سيطرة كاملة\n\nكل التحايا لك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ee-200/121495/4", "user": "user2491", "ts": 1329904655000, "tid": 121495, "pn": 4}}', 1329904655000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1406511-ee380', 'stk-user2352', 'EE 380', 'info', '{"desc": "تفضل هذي أفضل المصادر لمذاكرة هذا الكورس بالذات 🌹\n\nhttp://www.mediafire.com/download/7b43gh92ok7pw69/EE-380+ONLINE.rar\n\nهذا ONLINE LECTURES من تأليف دكاترة القسم المتميزين\nافهم منه وأعد حل الأمثلة والمسائل في نهاية كل LECTURE\nوهذي تغنيك عن شرح الكتاب وتحتاج فقط لحل بعض مسائل الكتاب بعد الفهم من هذي اللكتشرز\n----------------------------------------------------------------------------------------\nhttp://www.youtube.com/watch?v=EHDv59CYrYM&list=PL523E858F1BFD8559&index=2\n\nهذي شروحات فيديو لمهندس CONTROL في كلية ينبع الصناعية لنفس الكورس هنا ،،\nشرح ولا أحلى بالعربي حتى لجميع محتويات الكورس 🤠\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166427/2", "user": "user2352", "ts": 1413847275000, "tid": 166427, "pn": 2}}', 1413847275000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p272585-ee380', 'stk-user2639', 'EE 380', 'info', '{"desc": "غياث الدين أنا أتوقع\n\n1- إما أن تكون طالب من جنبها تقول إذا أحسن الناس أحسنت وإذا أساؤا أسأت يعني باختصار تسمع الشباب يقولون الإختبار صعب وتردد مثلهم كالببغاء (أقصد الشباب اللي مايدرون وش الee380 داخلين التخصص هذا بالغلط) وهذي والله مصيبة\n\n2- وإما تكون طالب على قد حالك جاب الدكتور اختبار فيه فكرة وحده أو فكرتين و خربت الإختبار ولا عرفت تحل\nوهذي أنا أنصحك تروح مستوصف الجامعة لأن عندهم طبيب نفسي كلمه عن حالتك وأنا أسأل الله أن يشفيك ويشفي من هم على شاكلتك اللي إذا ما عرف يحل يبدأ يقول الدكتور ما يعرف يشرح أو الختبار صعب يا جماعة خلاااااااااااااااااااص اكبروا وتحملوا مسؤولياتكم ليش تحطون الخطأ على غيركم والله أنا أعتقد أن هذا هو سبب تخلف الأمة وهو عدم الشعور بالمسؤولية.\n\nشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63579/10", "user": "user2639", "ts": 1212967942000, "tid": 63579, "pn": 10}}', 1212967942000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p272595-ee380', 'stk-abdulaziz22', 'EE 380', 'info', '{"desc": "شقصدك بعبارة (( (أقصد الشباب اللي مايدرون وش الee380 داخلين التخصص هذا بالغلط) وهذي والله مصيبة )))\n\nاقول الحق على A+ يراعي وفاهم التخصص\n\nعلى قولتهم (( تطلع الشمس وتملي الحوش)) بكرة نشوف A+ حقتك وخل ال D للشباب الي على قولتك ما يدرون وش ee380 وداخلين التخصص بالغلط\n\n===============================================================\n\nههههههههههههههههههههههههه من جد سويت قلق\n\nياخي قهر والله تذاكر وتجيب العيد\n\nعالعموم شي خلص وراح بس حبيت اخذ راي الطلاب لا يكون بس انا عيدت\n\nاهم شي العيد جمااااااااااعي وعلى قوله الدكتور مسعود بنص الاختبار\n\n(( ياعمي الشغلة افرج )) و (( اطلع على نوتاتك ))\n\nبالتوفيق للجميع في باقي الاختبارات\n\nتصحبون على خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63579/14", "user": "abdulaziz22", "ts": 1212969323000, "tid": 63579, "pn": 14}}', 1212969323000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p900741-ee380', 'stk-daredevil', 'EE 380', 'info', '{"desc": "هلا حبيبي دارك نايت\nانا درست مع الدكتور السمستر اللي طاف ee 380 ان شاء الله اقدر افيدك 🙂\n\nمن ناحيه التصحيح باالنسبه لي كنت اطلع من الاختبار اشوف ال key solution بعد مايعمله ابلود في الويب سيتي وتكون درجتي نفس اللي كنت متوقعها وفي ميجر تو كانت اعلى … فمررات يعطيك حقك ومرات يساعدك يعني تقدر تقول على حسب صعوبة السؤال\n\nمن ناحية شرح باالنسبه لي بداية السمستر كان شرحه ممتاز بس مع الوقت صار شرحه سيء جداا هو عيبه انه يشرح على البروجكتور ويقعد طول المحاضره يشرح الكونسيبت ونادر مايعطي اكسامبلز فكنت اضيع معه لكن باالنسبه لي اللى كنت اسويه اني وقت المحاضره اشغل نفسي باي ماده ثانيه وكنت اروح للمدرس دايم في الاوفس اور ( على فكره هو يقدر الطلاب اللي يحضرون للمكتب دايم ) واخليه يشرحلي كل شي ماكنت فاهمه والحمد لله في الاوفس اور الشرح مررره ممتاز\n\nمن ناحية القريد النهائي باالنسبه لي ماقصر معي وخذت اكثر من اللي كنت استحقه\n\nباالنسبه للمقارنه مع احمد مسعود فانا في الحقيقه ماسبق لي اني اخذت كورس معه فما اقدر اقارن لكن في نقطه اضافيه حاب اضيفها للدكتور هاكان اللي هي انه دايم يحاول يعمل اي حاجه تكون في مصلحة الطالب مثلا في البدايه كان يعطينا كويزات صعبه وكانت درجات الطلاب مرره ضعيفه والافرج يكون 2 او 3 من 10 بعدين صار يعطينا كويز ملتبر شويز والافرج من بعدها صار 6 الى 7 … الشي الثاني انه عطانا بروجكت مرره صعب وطويل جدا فصار البروجكت عليه 2 % بعد ما كان عليه 5 % وميجر ون كان مرره طويل وساعتين ماكفت الطلاب فصار ميجر تو مدته ساعتين ونص وكانت كافيه لكل الطلاب ومن ناحيه التاخر والغياب ماعنده مشكله ولا يحاسب عليها كثير وسمعنا اشاعات انه زود لطلاب ال 205 درجات في ميجر تو\n\nباالنسبه لي هذا الدكتور ماندمت ابدا اني نزلت معه وبترتاح كثير معه اذا كنت مهتم وتتابع معه اول باول فاالله يكتب اللي فيه الخير لك 🌹🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/111917/2", "user": "DareDevil", "ts": 1315916346000, "tid": 111917, "pn": 2}}', 1315916346000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1113048-ee380', 'stk-mr.wswas', 'EE 380', 'srcU', '{"html": "بالمرفقات 🌹<br><br>​<span data-fid=\"stk-f1113048-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1113048-0": {"name": "ee380 121 syll.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2d790a7b2e56a18c0c9c6cdaadbcaa53706f9bf02bdb2259b43fb72f2299315b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/134129/2", "user": "mr.wswas", "ts": 1352157127000, "tid": 134129, "pn": 2}}', 1352157127000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8598-ee380', 'stk-user8598', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 122\nee380\n\nبنود التقييم :\n\nالتحضير :\nيمرر ورقة تسجل اسمك ونهاية المحاضرة يقرأ الاسماء\nطريقة الشرح :\nيكتب على السبورة وكاتبته منظمة ويشرح الكونسبت وبعدها يحل مسألة على الموضوع\n\nالكويزات :\nسهلة الى متوسطة وغالبا يكررها من الاولد كويزز بعضها موجود بالموقع حقه\nالمياجر:\nمياجره متوسطة وطريقتها هو يقول لك انها نفس الاول اكزام بس تختلف الافكار يعني نفس صيغة السؤال بس\nبفكرة جديدة او نفسها بالضبط\nالفاينلات :\nالفاينل جاء مستواه اصعب من المياجر وكان فيه اسئلة صعبة\nالقريد النهائي:\nb\nالصوت:\nواضح ويشرح بعربي بعض المرات\nإضافات :\n\nالدكتور اخلاقه حلوة ومتفاهم بالاوفيس ودائما متواجد ب59\n\nهوم وركاته شوي طويلة واذا حليت الهوم ورك بنفسك اظمن انك بتبدع معه\nالتصحيح يدف فيه وخاصة الكويزات وايضا بالمياجر تخبص بالسؤال تلقاه معطيك اكثر من النص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1297035-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/12", "user": "user8598", "ts": 1385774527000, "tid": 98393, "pn": 12}}]}', 1385774527000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6737-ee380', 'stk-user6737', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بعيداً عن العاطفة وملتزماً بالحيادية في بنود التقييم\n\nالمادة ee380\n\nبنود التقييم :\nالتحضير :\nيحضر بورقه بعد 10 دقائق ويشيك عادة قبل نهاية الكلاس لا يخصم على الغياب إلا بعد عدد محدد\nطريقة الشرح :\nيكتب نوت على السبورة وامثلة وقصص من الواقع ويربط المادة بالحياه العملية وحتى اللاب وكذلك الماتلاب عكس المدرسيين الأخريين\nالكويزات :كلها مكررة وموجودة مع حلها سابقاً من الأولد كويزز بدون تغيير أي حرف أورقم ولكن عليك دراستها قبلاً وتأتي مثل أمثلة النوت وشرحه\nالمياجر:\nسهله إلى متوسطه ميجر 1 كان 3 أسئلة سؤالين افكارهم مطابقة للأولد ميجرز و سؤال كبي بيست من أولد ميجر وأغلب الطلاب ما حلوه\nو ميجر 2 كان عبارة عن 3 أسئلة مشابهه للكويزز والأولد ميجرز بنسبة 90%\nمثل شرحه في الكلاس وتشبه إلى حد كبير المياجر القديمة و ربما ترى سؤال كبي بيست من ميجر قديم\nالفاينلات :\nمتوسط إلى صعب تغيير في طريقة الأسئلة نوعاً من من الماتيسريال القديم لميجر 1 و2 + الميجر الجديد مثل شرحه في النوت و سؤال كبي بيست من الهومورك\nالقريد النهائي: A\nالصوت: واضح جداً يشرح بالعربي والإنجليزي\nإضافات :محترم في التعامل مع الطلاب و وحبوب وفلاوي في الكلاس والأوفس أور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1379880-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/15", "user": "user6737", "ts": 1402755698000, "tid": 98393, "pn": 15}}]}', 1402755698000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-ee380', 'stk-magbool', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ee380 - 152\n\nبنود التقييم :\n\nالتحضير :\nورقة تمر ، كان بداية السمستر يشيك ع الأسماء نهاية الكلاي بعدين بطل.\n\nطريقة الشرح :\nالشرح غالبا واضح، يشرح الكونسبت بالبداية بعدين يعطي عليها أمثلة ، لكن أحيانا يغلط ويضيع ويضيعنا معاه.\n\nالكويزات :\nأغلبها سهلة ، وقريبة من الكويزات القديمة.\n\nالمياجر:\nسهلة ، برضو نفس طريقة الاولد اقزامز.\n\nالفاينلات :\nصعب جدا.\n\nالقريد النهائي: B\n\nالصوت: واضح جدا\n\nإضافات :\nالدكتور بشكل عام جيد، لكن المادة ما عجبتني أبدا، طريقة تعامله مع الطلاب في الكلاس مش كويسة مرة ،يعني لمن تسأله سؤال بيجاوبك مع شوية تحقير واستهجان لسؤالك، بروجيكته مش صعب، عبارة عن تجربة تسويها باللاب وتكتب ريبورت عنها، بس للأمانة أعطاني قريد أعلى مما كنت أتوقع بكثيييير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451074-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/16", "user": "magbool", "ts": 1464990398000, "tid": 98393, "pn": 16}}]}', 1464990398000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo-da7m-ee380', 'stk-abo-da7m', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE380 الفصل 161\n\nالتحضير :\nورقة تمر على الطلاب يكتبون به أسماءهم ولا حصل وقت ببعض المحاضرات يشيك من الموجود ويتأكد من الورقة.\n\nطريقة الشرح :\nيشرح بالعربي معظم الوقت ويتكلم كم جملة بالإنجليزي.\n\nيبدأ يسولف ويعطي خلفية ومعلومات مختلفة عن الموضوع عشان يدخلك بجو اللي بيتكلم عنه.\n\nثم يكتب عنوان رئيسي بالسبورة ويبدأ يشرح ويكتب. شرحه شوي شوي ومبسط وتقدر تتابع معه.\n\nيحضر بشكل جيد للدرس ويجي يعطيك وزبدة صفحات كثييرة بالtextbook ويشرحه بتمكن.\n\nخطه غير مقروء بعض الأحيان ولازم تكتب معه لإن ما تلقى اللي يكتبه على السبورة بالبلاك بورد أو على شكل نوتس.\n\nالكويزات :\n\nيعطي من 5 إلى 6 كويزات ( كويز بعد كل واجب)، شبيهة جدا بكويزاته القديمة وسهلة بالمجمل.\n\nالمياجر:\n\nسهلة مرة ونفس اللي يشرحه ( لدرجة بعص الأحيان يكتب استخدم … مثل ما تكلمنا بالكلاس) + تقسيمه للدراجات كويس، كل فقرة عليه درجة.\n\nالفاينلات :\n\nصعب ومفاجئ، مختلف عن المياجر ويعتمد كثير على فهمك واعتقد هو اللي يفرز فيه الطلاب بالنهاية.\n\nبالفاينل لازم يجي سؤال من آخر 5 محاضرات ( اللي هي بتكون عن تصميم نظام بمواصفات محددة) تحتاج تركز معه كثير بهالمحاضرات عشان تحسن فرصك بالحل.\n\nالقريد النهائي:\n\nA إلى A+\n\nالصوت:\n\nيبدأ خفيف ببداية المحاضرة ثم يرتفع ويصير واضح.\n\nإضافات :\n\n* بروجكته من سنين وهو نفسه ( تسوي تجربة وتكتب فيها ريبورت مفصل + حنا عطانا استبانة نقييم فيها تجربتنا وكان عليه جزء من درجة البروجكت)\n\n* الدكتور فاااهم جدا ومطلع بمجاله كثيير، بتلاحظ أيام يستطرد ويقولك عن أبحاث جديدة بالمجال ووش اللي قاعد يصير فيه هالأيام.\n\n* أكثر شيء أعجبن فيه: يحط مجموعة مراجع وكتب مفيدة ودسمة بالبلاك بورد ويفتح لك المجال تبحر بأي موضوع أعجبك بالكلاس.\n\n* أخذت معه قريد أحسن من ما توقعت.\n\n* عيبه الأساسي والكبير مثل ما قال اللي قبلي: ما يرحب بالأسئلة ويتنرفز ويعامل أسئلة الطلاب باحتقار غريب بعض الأحيان + ينفعل كثير لا شاف طالب يسولف وممكن يسفل فيه لو طول.\n\n* يظل من أفضل الدكاترة يالكهرب بالنسبة لي، ركز معه واكتب أول بأول وراح يشيل عنك عبء كبيير من الكورس لإنه يبسط كثير أشياء معقدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467222-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/17", "user": "abo-da7m", "ts": 1485703560000, "tid": 98393, "pn": 17}}]}', 1485703560000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-ee380', 'stk-mr.a1', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f153258", "n": "Dr. Waqas Afzal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 EE 380(LAB)\n\nالتحضير :\nبداية اللاب بالاسماء.\n\nطريقة الشرح :\nيبدأ الشرح بمقدمة عن التجربة والنظرية اللي حولها ، ويستعمل السبورة في حال احتاج يوضّح شيء محدد. شرحه جيد جدا إلى ممتاز.\n\nالكويزات :\nأخذنا ثلاث كويزات مستواها وسط ، اختيارات ويجيبها من أسئلة الـ discussion نهاية كل لاب مع مفاهيم التجربة ، يعني لازم تشتغل وتحاول تفهم وش قاعد تسوي + تقرأ المانيوال كويس.\n\nالمياجر:\nاختبار عملي واحد ، صلخ بمعنى الكلمة (من ناحية عدد الأسئلة ، طريقة كتابتها ، والوقت) ، لدرجة الآفرج ١ من ٤.\n\nالفاينلات :\nفاينل شامل لكل التجارب وطويل ، بتشوف أسئلة من كل التجارب اللي أخذتها. نظامه اختيارات مثل الكويزات ، ومستواه عادي مو صعب مرة.\n\nالقريد النهائي:\nA\n\nالصوت:\nعالي جدا ، آكسنت باكستاني.\n\nإضافات :\n١. من أفضل الأساتذة اللي درست عندهم. شرح ممتاز بالرغم من أن ماتيريال اللاب ما يساعد ، لكنه يبذل جهده عشان يوصل المعلومة لأقصى حد ممكن ، غير كذا تعامله ممتاز مع الطلاب ولو حصّل عندك مشكلة في التجربة يساعدك ويشرح لك وش الاخطاء اللي سويتها.\n٢. ريبورتاته خفيفة جدا ، أوبجكتف وشغل اللاب مع الـ discussion وخلاص. إذا الريبورت مليان صور يوصل ٤ صفحات بالكثير.\n٣. يحط hints على البلاك بورد ، تساعد الطلاب في حل البريلاب والدسكشن.\n٤. أسلوبه في اللاب (خصوصا إذا كان كله ماتلاب) أنه يشرح جزء ويخلي الطلاب يطبقون معه. الطريقة حلوة عشان يضمن الكل يفهم لكنها تاخذ وقت ، وبالتالي تقريبا نص اللابات ياخذ فيها الوقت كامل أو حوله.\n٥. ما شاء الله عليه ، في حياتي كلها ما شفت أحد أسرع منه في التصحيح. يختبر الطلاب ويصحح ويرصد ويرفع على البلاك بورد في نفس اليوم ، غير كذا منظم ويحدث الدرجات أول بأول عشان تكون عارف وضعك صح.\n\nلو حصل لي آخذ مادة وحصلت اسمه من ضمن الأساتذة ، ما راح أتردد إني أسجل معه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485130-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-waqas-afzal/153258/6", "user": "Mr.A1", "ts": 1514403782000, "tid": 153258, "pn": 6}}, {"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 EE 380\n\nالتحضير :\nبعد ١٠-١٥ دقيقة يمرر ورقة على الطلاب. يزعل من اللي يتأخرون وينبه حول الموضوع كثير. مرات يشيّك على ورقة الحضور بنفسه ، بعد ما لاحظ إن فيه ناس يحضرون وهم مو موجودين.\n\nطريقة الشرح :\nعلى السبورة بشكل كامل. يتكلم ويشرح النقاط بشكل شفهي ويستعمل السبورة لكتابة النقاط المهمة والاشتقاقات وحل الامثلة. مستوى الشرح جيد جدا إلى ممتاز.\n\nالكويزات :\n٦ كويزات ، قال بياخذ أفضل ٥ منها. مستوى الكويزات عادي ، وغالبا يجيبها من أولد كويزز أو أسئلة الهومورك.\n\nالمياجر:\nطبعا مثل ما تعرفون نظام هالمادة كل دكتور لحاله. مياجر د. مسعود سهلة ، أحيانا يجيب أسئلة نسخ لصق من اختبارات قديمة وما يغيرها. مرات -مثل ما صار معنا هالترم- يجيب سؤال فيه فكرة جديدة في أحد الاختبارات. أشوف تصحيحه عادل.\n\nالفاينلات :\nصلخ بما تعنيه الكلمة ، احتفل فينا في آخر يوم 😆. مستوى الفاينل أعلى من المياجر بكثير ، لذلك من المهم تكون فاهم مضبوط وحافظ القوانين اللي ممكن تحتاجها عشان تطلع بأفضل درجة ممكنة.\n\nالقريد النهائي:\n+B\n\nالصوت:\nمنخفض في البداية ، بعد ٥ دقايق يصير عالي جدا. لغة الشرح مخلوطة بين عربي فصيح ، عربي بلهجة أردنية ، وانجليزي.\n\nإضافات :\n١. ما راح تلقى اللي يكتبه على السبورة في البلاك بورد ، وحتى كتابته مو مرتبة على السبورة ، والخط أحيانا غير مفهوم ، فبتتعب اشوي وانت تاخذ نوت معه.\n٢. شرحه أحيانا يخالف الموجود في كتاب المادة ، أو يستخدم طرق مختلفة اشوي عنه.\n٣. الدكتور يتضايق أحيانا من أسئلة الطلاب ، وتحسه يجاوب بدون نفس إذا أحد سأله في الكلاس.\n٤. حسب ما عرفت من الشباب اللي راجعوه على المياجر ، صعب جدا تطلّع منه درجات على التصحيح.\n٥. ما قد رجّع لنا هومورك صححه ، وحتى درجة الكلاس وورك ما عرفناها ، نزّل القريد في البورتال على طول.\n٦. أعطانا بروجيكت طويل نسبيا ، والشغل كله على الماتلاب. هو بروجيكتاته نظام أنت وحظك ، مرات يعطي شيء خفيف ومرات دسم.\n٧. أحد الأشياء اللي أعجبتني في الدكتور أنه ينزّل لك مجموعة كتب في التحكم والمواضيع المرتبطة به على البلاك بورد ، تقدر تستخدمها كمراجع.\n٨. الآفرج عنده بين C و +C ، لذلك كونك قريب من الآفرج ما يعني إنك تطلع بقريد كويس.\n\nفي المجمل ، أشوف الدكتور كويس وبتستفيد منه كثير في مجاله ، لكن أنصحك تجمع درجات قد ما تقدر في كل شيء -حتى في اللاب- ، إذا كنت تبي تطلع بقريد عالي معه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485952-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/18", "user": "Mr.A1", "ts": 1515671971000, "tid": 98393, "pn": 18}}]}', 1514403782000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ali_g-ee380', 'stk-ali_g', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE 380 - 171\n\nالتحضير :\nورقة تمر\"يتضايق من التأخير\"\n\nطريقة الشرح :\n\nشرح والكتابة في السبورة بطريقة التقليدية, حاول تكتب معاه وتكتب ملاحظات عليها لان الكتاب في طريق والدكتور في طريق ثاني\nوانصح بعدم التصور عشان ما تنكب نفسك لان خطه صعب تفهمه وملخبط.\nوالدكتور متمكن في الشرح.\nالكويزات :\nأغلبها سهلة ، راجع اولد كويز يجبها بنسخ, اغلب الشعبة فل وما عرفت الا في اخر كويز.\n\nالهوموورك :\nمستواه اصعب من ميجر والفاينل وهذي فرصة تختبرنفسك اذا انت متمكن في الدرس.\n\nالمياجر:\n\nميجرين سهل والافرج عالي.\nمن كل ميجر فيها سؤالين سهل يجيبها من اختبارات القديمة وسؤال الثالث وسط وفيه افكار جديدة .\nالفاينلات :\nتصفية حسابات الفاينل, الميجرين كان هدية لكن الفاينل طريقة الاسئلة وسط الى صعب لانه اغلبه كونسيبت, اغلبه مفاهيم المادة تحتاج قراءة والبحث من النت عشان تستوعبها صح.\n\nالقريد النهائي: A++.\n\nالصوت: واضح وعالي (ميكس عربي وانجلش).\n\nإضافات :\n\nهو اكثر دكتور متمكن في مادة التحكم وراح يربط لك اشياء كثيرة من الي تدرسه, لان مادة فيها الصعوبة في تطبيق النظرية للواقع.\nصح انه اخلاقه سيئة لكن وش همك فيها, اهم شي الفهم والشرح والقريد وسلامتك.\nالبروجيكت كان نظري ولا شفت فيها فائدة مجرد تعبية كلام, لكن اذا انت مهتم بتطبق نظرية التحكم في شغله اسمها PID controller اشوفه اسهل من leg/lag compensator لانه ما يحتاج تطلع Transfer Function للسيستم وهذي قصة عشان تجيبها ماراح تدرسه, معليش شطحت بس اغلب مشاريع الكهرباء على الورق\n🚬 1. .\nالتصحيح جدا متعاون يركز التصحيح على الفهم والطريقة الحل ولا على الرقم النهائي, مرة في ميجر 2 كان سؤال من معادلة من درجة الرابعة\n🤪 1. والحاسبة ما تساعدك تحتاج حاسبة غير عن العادية, او طلع شطارتك في ماث والوقت يخلص, شرحت له بسالفة وزودني عليها.\nما راح تعرف درجاتك في كلاسووك بتشوفها في بورتال.\nالتقييم الي فوق ما يمثله (3/5!!) من افضل دكاترة في القسم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504239-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/20", "user": "Ali_G", "ts": 1546150558000, "tid": 98393, "pn": 20}}]}', 1546150558000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-some_ee-ee380', 'stk-some_ee', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98393", "n": "Dr. Ahmed Masoud", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE380-212\n\nالتحضير : بنص الكلاس ورقة تمر على الطلاب، الدكتور يعرف ان في ناس يحضرون غيرهم وصاد واحد بس ما سوا شي ومريح راسه، بس الدكتور يكره انك تجي متأخر واذا جيت متأخر مرة بيقولك لا تدخل.\nطريقة الشرح : على السبورة يكتب ويشرح المنهج ويفصل فيه ويحب انه يضرب أمثلة تساعد في الفهم وتشاركوا معه ويعصب اذا ما احد شارك بالكلاس بس ما يسوي شي ويكمل شرح عادي. يبدأ الكلاس بإيش وقفنا عنده الكلاس الماضي بسرعة ثم يبدأ في الجديد ودائما يبدأ بشرح نظري بحت ثم بنهاية الشرح بيعطي أمثلة ويحلها بس غالبا تكون أمثلة مبسطة عشان وقت الكلاس ضيق. أغلب الطلاب ما كان يعجبهم شرح الدكتور لكن عن نفسي أشوف شرحه ممتاز واعتمدت عليه بشكل كبير والحمدلله كانت درجاتي كويسة في المياجر والفاينل. عيب الدكتور في الشرح انه ايام يشطح بالأمثلة بشكل كبير لكن عن نفسي كنت أشوف الشطحات ذي تكسر ملل وثقل المادة.\nالكويزات : سهلة وكلها تكرار من الكويزات القديمة أو الواجب وأحيانا تكون نفس الأرقام.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: عالي لو أنت بأول السيب بتسمعه ما شاء الله\n\nسلبيات:\n\nالبروجكت كان غريب وغير مفهوم وما عرفنا حله.\nبعض الأسئلة في الهومووركات اللي هو مسؤول عنها تكون طويلة جدا لكن استخدم الماتلاب والمصادر على النت وبتساعدك تحلها بوقت أقل.\nالدكتور يفضل أنك ما تقاطعه ولا تسأل غير لما يخلص شرح.\nإيجابيات:\n\nالدكتور قمة في الأخلاق والتعامل من أفضل الدكاترة اللي نزلت عندهم من هالناحية ولما تروح له المكتب تلاقيه عسل والله ويفيدك مرة.\nاذا في شيء صار خطأ الدكتور ما يعاند وبالعكس يعتذر ويعدله على طول راجعته بخصوص أكثر من موضوع وكل مرة يحرجني بتعامله ودائما يضحك ويمزح.\nالبروجكت حقنا كان صعب الحل حقه ولما عرف الدكتور تعاون بالتصحيح مرة اذا سلمته شيء منطقي بيعطيك درجة كبيرة.\nتصحيح الدكتور ممتازوعادل يعطي بارشل اذا سويت شي متعلق بالسؤال ولا يخسفك الا لو نموذج التصحيح محدد درجات السؤال.\nشرح الدكتور يركز على انك تفهم المادة كويس وبعدين تستنتج الحل وكثير من الأسئلة في الفاينل والميجر كنت أحلها من شرح الدكتور.\nإضافة للنقطة السابقة كنت محشور بمذاكرة فاينل 380 لأن كان قبلها عندي اختبارات ثقيلة واعتمدت على مقاطع الدكتور في اليوتيوب والحمدلله جبت درجة كويسة في الفاينل.\nالدكتور فاهم مرة ما شاء الله ويذكر لك أمثلة من الواقع على تطبيقات اللي تدرسه وأيام يذم في المنهج لأنه ما يتطابق مع السوق والتوجه. لو حبيت تستفيد أكثر ممكن تتواصل معه في المكتب وبيفيدك بشكل مفصل.\nالدكتور متواجد بالمكتب لساعات طويلة ويرد على الايميل بسرعة.\nلو لقيت الدكتور بمادة ثانية بنزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534515-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-masoud/98393/25", "user": "Some_EE", "ts": 1653904002000, "tid": 98393, "pn": 25}}]}', 1653904002000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8180-ee380', 'stk-user8180', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه في 101\nالتحضير : جانا في اول محاضره قال التحضير عليه 5 درجات ولا حضر طول السيمستر\nطريقة الشرح : يشرح على السبورة ونوته روووعه\nالكويزات : سهله وتركز على شرحه بالمحاضره. بس إنسى انك تعرف درجتك بالكويز\nالمياجر: مياجره متوسطة.\nالفاينلات : الفاينال جانا سهل مرررره\nالقريد النهائي: أعطيه a\nالصوت: واضح\nإضافات : الدكتور يدرس ee380 بس ومتمكن من الماده يشرحها بشكل مبسط وسهل واللي ينزلها مع دكتور ثاني راح يتعب بالمادة. لكن الدكتور يعيبه شي واحد اللي هو انسى انك تعرف درجت الكلاس ورك او تشوف ورقتك حقت الميجر الثاني. أنا اول مانزلت معه سمعت ان الدكتور ما يعطيك حقك في القريد لكن اللي شفته العكس تماماً الدكتور يعطيك حقكبالضبط من غير نقص ولا زوود.\nأنصح فيه وبقووووة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p781030-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/7", "user": "user8180", "ts": 1296739105000, "tid": 98522, "pn": 7}}]}', 1296739105000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-ee380', 'stk-user6130', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله سمستر “112” EE 380 :\n\n(1) التحضير : بداية السمستر كان ما في تحضير بعدين بعد ميجر 1 قام يحضر بورقة و نكتب عليها رقم ID .\n\n(2) الشرح : الدكتور هذا ميزته إنه راااايق و يشرح لك شرح راااايق و يعطيك الزبدة يعني ممتاز شرحه الراااايق و يكتب نوت راااايقه بعد.\n\n(3) الكويزات : عطانا 5 كويزات واحد صعب و البقية تتراوح مابين السهولة و التوسط في الصعوبة بس ما أدري هو خذاهم كلهم و لا لا.\n\n(4) المياجر و الفاينل : هو اللي يحطها و كانت على النحو الآتي 🤠 :\nميجر (1) : وسط بس طويل “سؤالين بس” ، ميجر (2) : سهل “سؤالين بس” ، الفاينل : وسط بس طويل \" أربع أسئلة \".\n\n* إضافات :\n- عطانا بروجكت عبارة عن مسألة \" Design \" هو شارحها في الكلاس بس زيادة عليها إنك تسوي للسستم سميلتد في المات لاب.\n\n- بالنسبة لدرجة الكلاس ورك و الفاينل ما عطانا إياها نزل الفاينل قريد على طول في البورتال.\n\n- اللي يبي يأخذ الزبدة في كورس 380 و ما يتعب واجد ينزل معه.\n\nالقريد النهائي : A .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048117-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/15", "user": "user6130", "ts": 1338390328000, "tid": 98522, "pn": 15}}]}', 1338390328000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4207-ee380', 'stk-user4207', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم ١٢٢ - ee380\n\nالتحضير ورقة تمر على الطلاب\nالكويزات : ٤ كويزات مويه سهله مره\nالمياجر : متوسطة و من النوت\nفاينل : مويه و برضو من النوت\nطلعت بقريد حلو\n\nحبيب و عسل و يحببك في المادة\nالله يذكره بالخير من جد بطل\nو كنت احسه متساهل بالتصحيح\n\nتقيمي للمدرس a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1229387-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/16", "user": "user4207", "ts": 1369760663000, "tid": 98522, "pn": 16}}]}', 1369760663000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-ee380', 'stk-hammmod', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98522", "n": "Dr. Husain Al-Dawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE380 Term 162\n\nالتحضير:\nيوميا ورقة تمر على الطلاب ويعد الحاضرين. اذا تأخرت فوق 10 دقايق يمكن يعطيك كلمة والا نظرة.\nطريقة الشرح : The most Classical way يكتب نوتات على السبورة ,ويشرح شرح مبسط ورايق وانقل معه، الحق ان نوتاته مرة رهيبة ومختصرة وفيها زبدة الكورس بدون زيادة، الكلاس الوحيد اللي كنت أكتب فيه، بس أكتب وأنا مرتاح. ويعطيك اكزامبلز كثيرة وما يركز على الكونسبت أو الماث بيهاند ات. طبعا الدكتور ما شاء الله تبارك الله فيه ميزة خارقة، انه يكتب النوتات والاكزامبلز من راسه، يوم واحد بس جاب معه ورقة فيها قوانين، والا طول الترم ما شاء الله بدون.\nالكويزات:\nسؤال واحد بسيط مشابه لاكزامبل حليتوه بفرق بسيط.\nالواجبات:\nهذي ميزته العظمى، مريحك لا واجبات ولا بروجكت ولا خرابيط.\nالمياجر:\nهو يكتبها، كانت وسط ومشابهة للأولد اقزامز حقته، دورها. (طبعا فيه حركة وهي اذا جاب لك سؤال على درس في الكويز فغالبا مهوب جايب لك سؤال عليه في الميجر)\nالفاينلات :\nنفس المياجر\nالقريد النهائي:\nA\nالصوت:\nواضح أغلب الوقت انقليزي.\nإضافات :\nالدكتور ما يتفوت، يريحك مرة في هالكورس وبتشوفه سهالات ويمكن أسهل مادة في التخصص. نوتاته مختصرة وما يشرح لك كل المواضيع اللي في الكتاب، لو كان الكورس كومون يمكن تتورط. يعيبه يمكن انه ما يتعمق في المفاهيم كثير ويوريك تطبيقات حقيقية أو أخبار جديدة عن الموضوع. إذا بس تبي الزبدة وقريد خذ معه. اذا تبي مفاهيم أكثر وتطبيقات ومعرفة أوسع للموضوع وبروجكت رح لأحمد مسعود.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474033-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/husain-al-dawish/98522/18", "user": "hAmMmOd", "ts": 1496053217000, "tid": 98522, "pn": 18}}, {"id": "stk-dr-f153258", "n": "Dr. Waqas Afzal", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE380 LAB Term 162\n\nالتحضير : زي غيره كل بداية لاب ونفس البوليسي.\nطريقة الشرح : يبدأ بشرح الكونسبت والماث على السبورة وصراحة مرررة يفهم ويحببك في الموضوع. وبعدين تشتغلون في قروبات سواء ماتلاب أو هاردوير. شرحه ممتاز ومتعاون وحريف ماتلاب.\nالكويزات :عطانا ثلاث كويزات متوسطة، ذاكر لها نص ساعة قبل اللاب تكفيها ان شاء الله بشرط تفهم وش فاعد تسوي في اللاب.\nالفاينلات : كان طويل وشامل ومشابه للكويزات، يركز على المفاهيم الأساسية.\nالقريد النهائي: A+\nالصوت: واضح وانقليزيته ممتازة\nإضافات :\nالأخ وقاص أفضل من درسني لاب، خصوصا 380، عيال في السكاشن الثانية مدرسينهم ما يشرحون مثله. طيب ومتعاون ولو ترسل له ايميل يرد عليك بسرعة البرق. لا تفوته.\nيحط لك هنت لأسئلة الريبورت والبريلاب في البلاك بورد. وما يدقق في تنظيم الريبورت كثير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474037-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-waqas-afzal/153258/5", "user": "hAmMmOd", "ts": 1496053919000, "tid": 153258, "pn": 5}}]}', 1496053217000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_only-ee380', 'stk-_only', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f98533", "n": "Dr. M Abdur-Rahim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم و رحمة الله و بركاته …\n\nالدكتور عبدالرحيم أخذت عنده ee380 في سمتستر 102 …\n\nالتحضير: ورقة تمر في بداية الكلاس\n\nالشرح: أقل من المتوسط و يجيب النوم حتى لو ما كان فيك النوم أصلاً 🙂 و صوته ضعيف و كان يعطينا سلايدات نذاكر منها و لكن كانت غير جيدة\n\nالكويزات: سهلة و تقريباً مثل أسئلة الهومورك\n\nالمياجر: متوسطة الصعوبة يعني إذا ذاكرت بتجييب قريد حلو\n\nالفاينل: بصراحة كان أصعب من المياجر و لكنه ليس مستحيل يعني يعتبر صعب نوعاً ما مقارنة بالمياجر\n\nالجريد النهائي له: C+\n\nفي الأخير إذا تبي قريد بدون فايدة علمية نزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p985610-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-abdur-rahim/98533/17", "user": "_ONLY", "ts": 1329209730000, "tid": 98533, "pn": 17}}]}', 1329209730000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imported50-ee380', 'stk-imported50', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f115354", "n": "Dr. Hakan K&ouml;roğlu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده ee 380\n\nبنود التقييم :\n\nالتحضير : يحضر بعد عشر دقايق تقريبا … ولو تحضر متآخر بيحضركـ آخر شي …\nطريقة الشرح : يشرح على سلآيدآت… ويشرح كونسبت ومثال او مثالين من الكتآب ويطلب منكـ في الكلاس تشتق معادلآت ووشلون طلع القآنون و اشياء نصهآ مآ تفيد لآ في الميآجر ولآ الكويزآت …\n\nالكويزات : من اسئلة الهوموركـ … ورآح يطلب هوموركـ تقريبا كل اسبوع… وهوموركآت 40% منهآ اسئلة مآلهآ علآقة بالمنهج ويبيلك وقت عشان تفكـ شفرة الآسئلة … ونآدر تشوف ارقآم في السؤال … ما يتعامل الآ بالرموز\n\nالمياجر: متوسطة … بس لآزم في كل ميجر سؤال لحسه ونفس الشي يبيلكـ وقت عشان تفهم السؤال … وتصحيحه كل شي يبي فيه بروف … وما اتوقع احد عندهـ قد خذ فول مآركـ …\n\nالفاينلات : الله اعلم …\n\nالقريد النهائي: اعطيه -c\n\nالصوت: صوته يجيب النوم شوي … بس وآضح ولهجته وآضحه\n\nإضافات :\n\nالدكتور حبيب وآخلآق ومتسآعد مره في الآوفيس … بس مشكلته يحسب كل الطلآب مستوآهم عالي مرره وفآهمين كل شي … طلب منآ بروجكت صعب … لو بحلف انه سينيور بروجكت بس نآقص الشغل العملي …\nما انصح احد ينزل عنده الآ اللي مستوآهـ عآلي مره مره في المآث …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p950300-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-k-ouml-roglu-hakan/115354/4", "user": "imported50", "ts": 1324334383000, "tid": 115354, "pn": 4}}]}', 1324334383000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahad_ahmad878-ee380', 'stk-fahad_ahmad878', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f115356", "n": "Dr. Samir A Al-Baiyat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 182 EE 380\n\nالتحضير :\nكل كلاس يمرر ورقة بداية الكلاس للتحضير و يسحبها بعد 10 دقائق.نادر مايسحب على التحضير يمكن بس كلاسين ماحضر.\n\nطريقة الشرح :\nيفتح السلايدات على البروجيكتر ويقراهم لك وقليل جدا مايكتب شيء على السبورة. للأمانة الدكتور فاهم بس إيصاله للمعلومة لك عليه.\n.\n\nالكويزات :\nأعطانا 7 كويزات تقريبا ، جميع كوزاتة تكون في نفس اليوم اللي يكون فيه تسليم الهومورك و الكوز يكون من الهومورك أو قريبا جدا منه.حذف أسوأ هومورك و أسوأ كوزين.\nالمياجر:\nكان هو الوحيد اللي يدرس المادة وكان الميجر الأول نصفه خيارات و نصفه ريتن وصعب نوعا ما (الآفرج 60 من 100)\nالميجر الثاني كان كله ريتن و كان متوسط الصعوبة (الآفرج 58 من 100)\nالفاينلات :\nالفاينل كان ريتن و خيارات وكان من متوسط إلى سهل\n\nإضافات :\n\nالدكتورمستحيل يأجل تسليم أي واجب .\nكنت أواجه صعوبة في فهم المادة مع الدكتور لأنه حرفيا يقرأ من السلايدات حقته بدون حل للمسائل والمادة تحتاج واحد يوضح لك كيف تبدأ بالحل أو الرسم و السلايدات حقته جدا مختصرة و غير واضحه بالغالب.\nأغلب محتوى المادة موجود باليوتيوب وكان يختصر عليك وقت كثير بفهم المادة.\n4.جميع كوزات و مياجر و هوموركات الدكتور رفعتها في kfupm resources\n5.نهاية الترم ألغاء الدكتور البروجكت و وصار الهوموركات عليها 5 و الكوزات عليها 15", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509461-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-baiyat-samir-a/115356/4", "user": "Fahad_ahmad878", "ts": 1557268549000, "tid": 115356, "pn": 4}}]}', 1557268549000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-muath.12-ee380', 'stk-muath.12', 'EE 380', 'doc', '{"docs": [{"id": "stk-dr-f115356", "n": "Dr. Samir A Al-Baiyat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه EE380 الفصل 202 أون لاين\n\nالتحضير :\nتلقائي من زوم.\n\nطريقة الشرح :\nشرح الدكتور كويس، يستخدم السلايدات ويكون فيها أمثلة ويكتب بإستخدام القلم إذا احتاج يوضح أو يحل شيء\n\nالكويزات :\nكويزاته تكون عن الواجبات إذا حليت الواجب أو على الأقل فهمته أمورك طيبة وصحيح ما يقبل تأجيل الواجبات لو أيش.\n\nالمياجر:\nحولوها لميد وكان الاختبار من أصعب ما شفت مع أن الاختبار كان خيارات وكان open book تقدر تستخدم الكتاب أثناء الاختبار أو تطبع النوتات اللي تبغاها( في طلاب طبعوا نوتات الدكتور كاملة) ومع كل هذا الأفرج إذا كنت أذكر شي بالأربعين بسبب الصعوبة الزائدة.\n\nالفاينلات :\nالفاينل كان نفس طريقة الميد لكنه كان سهل جدًا.\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح.\n\nإضافات:\nالدكتور حبيب وتعامله طيب وشرحه كويس بس للأسف كان معنا طالب مزعج أثناء الكلاس من النوع اللي يسأل ويقاطع كثير ونوعية الأسئلة يا تكون أسئلة خاصة لدكتور ما لها دخل بالكلاس أو أسئلة تحس أنه يبي يبين لدكتور أنه فاهم أو أسئلة تحس انه يتحدى الدكتور فيها وللأسف الدكتور ما تعامل معه من البداية وبسببه نفروا بعض الناس من متابعة الشرح لكثرة مقاطعته حتى أنه سبب تأخر الدكتور عن المتيريال فتشوف كثير من الأحيان الدكتور مستعجل بسبب أنه متأخر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531206-ee380", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-al-baiyat-samir-a/115356/5", "user": "Muath.12", "ts": 1628781851000, "tid": 115356, "pn": 5}}]}', 1628781851000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
